from typing import List


class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        memo = dict()

        for idx, num in enumerate(nums):
            if target - num in memo:
                return [memo.get(target - num), idx]

            memo[num] = idx


sol = Solution().twoSum(nums=[2, 7, 11, 15], target=9)
print(sol)
